const defaults={cart:[],wishlist:[],user:null,addresses:[],pickups:[],orders:[],reviews:[],followed:[],newsletter:false,discount:0,voucher:'',delivery:'door',addressId:'',station:'',payment:'Card',step:1};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('kstore-v1')||'{}')}}catch{state={...defaults}}let selectedVariant='',activeImage='',lastFocus;
const save=()=>localStorage.setItem('kstore-v1',JSON.stringify(state));const getP=id=>products.find(p=>p.id===id);const count=()=>state.cart.reduce((n,l)=>n+l.qty,0);const subtotal=()=>state.cart.reduce((n,l)=>n+getP(l.id).price*l.qty,0);const ship=()=>state.delivery==='pickup'?14:35;const discount=()=>Math.round(subtotal()*state.discount*100)/100;const total=()=>subtotal()+ship()-discount();const route=()=>{let [path,query]=location.hash.slice(1).split('?');return {path:path||'/',params:new URLSearchParams(query||'')}};const go=path=>{if(location.hash==='#'+path){render();window.scrollTo(0,0)}else location.hash=path};const toast=s=>{const el=$('#toast');el.textContent=s;el.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>el.style.display='none',3000)};
function modal(title,body){lastFocus=document.activeElement;const d=$('#modal');d.innerHTML='<button class="close" aria-label="Close dialog" data-action="close">×</button><h2 id="dialog-title">'+esc(title)+'</h2>'+body;d.setAttribute('aria-labelledby','dialog-title');d.showModal();$('button,input,select',d)?.focus()}
$('#modal').addEventListener('close',()=>lastFocus?.isConnected&&lastFocus.focus());$('#modal').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const els=$$('button,a,input,select,textarea,[tabindex="0"]',$('#modal')).filter(x=>!x.disabled&&x.getClientRects().length);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}});
function card(p){return '<article class="product-card"><span class="discount">−'+Math.round((1-p.price/p.old)*100)+'%</span><button class="heart '+(state.wishlist.includes(p.id)?'saved':'')+'" data-action="wish" data-id="'+p.id+'" aria-label="'+(state.wishlist.includes(p.id)?'Remove from':'Add to')+' saved items">'+(state.wishlist.includes(p.id)?'♥':'♡')+'</button><a href="#/product/'+p.id+'" class="product-image"><img loading="lazy" src="'+p.image+'" alt="'+esc(p.name)+'"></a><div class="card-body"><div class="brand">'+p.brand+(p.official?' · Official store':'')+'</div><a href="#/product/'+p.id+'"><h3>'+p.name+'</h3></a><div class="rating"><span class="stars">★★★★★</span> '+p.rating+' <span>('+p.reviews+')</span></div><div class="price-row"><span class="price">'+money(p.price)+'</span><span class="old">'+money(p.old)+'</span><button class="quickadd" data-action="add-picker" data-id="'+p.id+'" aria-label="Add '+esc(p.name)+' to cart">+</button></div><div class="stock">'+p.stock+' items left<div class="stockbar"><i style="width:'+Math.min(p.stock*3,95)+'%"></i></div></div></div></article>'}
function section(title,items,link='/catalog',extra=''){return '<section class="section"><div class="section-head"><h2>'+title+extra+'</h2><a href="#'+link+'">View all &nbsp; →</a></div><div class="product-grid">'+items.map(card).join('')+'</div></section>'}
function header(){return '<div class="topline"><strong>A little more joy. A little less spend.</strong> Discover this week’s offers &nbsp; <a href="#/catalog?sort=discount">Shop now →</a></div><header><div class="wrap head"><button class="mobile-menu ico" data-action="menu" aria-label="Browse categories">☰</button><a href="#/" class="logo">kstore<span>●</span><small>✦</small></a><form class="search" id="search-form"><span class="ico" aria-hidden="true">⌕</span><input id="search-input" name="q" placeholder="Search products, brands and categories" aria-label="Search products" role="combobox" aria-expanded="false" aria-controls="suggestions" autocomplete="off"><button type="submit">Search</button><div class="suggestions" id="suggestions" role="listbox" hidden></div></form><div class="head-actions"><a href="#/help"><span class="ico">'+icon('help')+'</span><span><small>Need a hand?</small><b>Help center</b></span></a><a href="#/account"><span class="ico">'+icon('user')+'</span><span><small>'+ (state.user?'Welcome back':'Hello, welcome')+'</small><b>'+esc(state.user?.name.split(' ')[0]||'My account')+'</b></span></a><a href="#/cart"><span class="carticon ico">'+icon('cart')+'<span class="badge">'+count()+'</span></span><b>Cart</b></a></div></div><nav class="wrap nav"><a class="browse" href="#/catalog">☰ &nbsp; All categories</a><a href="#/catalog?official=1">Official stores</a><a href="#/catalog?category=Phones%20%26%20Tablets">Phones & Tablets</a><a href="#/catalog?category=Fashion">Fashion</a><a href="#/catalog?category=Home%20%26%20Office">Home & Living</a><a href="#/catalog?category=Electronics">Electronics</a><a href="#/catalog?category=Health%20%26%20Beauty">Beauty</a><a class="last" href="#/catalog?sort=discount">✦ &nbsp; Today’s deals</a></nav></header>'}
function footer(){return '<section class="newsletter"><div class="wrap"><div><h2>Good things. Straight to your inbox.</h2><p>Fresh finds, exclusive offers, and a little everyday inspiration.</p></div><form id="newsletter-form"><input type="email" name="email" placeholder="Your email address" aria-label="Newsletter email" required><button class="primary">Subscribe →</button><label><input type="checkbox" required> I agree to receive Kstore updates. Unsubscribe anytime.</label></form></div></section><footer><div class="wrap"><div class="footer-grid"><div><a class="logo" href="#/">kstore<span>●</span></a><p>Your everyday, upgraded.<br>Great finds. Fair prices. Delivered to you.</p><p>Accra, Ghana &nbsp; · &nbsp; Made for everyday life.</p></div><div><h4>LET US HELP YOU</h4><a href="#/help">Help center</a><a href="#/account/orders">Track your order</a><a href="#/info/shipping">Delivery & pickup</a><a href="#/info/returns">Returns & refunds</a></div><div><h4>ABOUT KSTORE</h4><a href="#/info/about">Our story</a><a href="#/catalog?official=1">Official stores</a><a href="#/info/sell">Sell on Kstore</a><a href="#/info/contact">Contact us</a></div><div><h4>SHOP WITH CONFIDENCE</h4><p>◇ &nbsp; Secure checkout<br>↶ &nbsp; Easy returns<br>▱ &nbsp; Trusted payment options</p><p>VISA &nbsp; Mastercard &nbsp; MTN MoMo</p></div></div><div class="footer-bottom"><span>© '+new Date().getFullYear()+' Kstore. All rights reserved.</span><span><a style="display:inline" href="#/info/privacy">Privacy</a> &nbsp; · &nbsp; <a style="display:inline" href="#/info/terms">Terms & conditions</a></span></div></div></footer><div class="demo-strip">Interactive demo · Purchases and payments are simulated · Data is saved in this browser</div>'}
function home(){return '<div class="home-top"><aside class="categories">'+categories.map(c=>'<a href="#/catalog?category='+encodeURIComponent(c[1])+'"><i>'+c[0]+'</i>'+c[1]+'</a>').join('')+'</aside><section class="hero"><div class="hero-copy"><span class="eyebrow">THE EVERYDAY EDIT · UP TO 40% OFF</span><h1>Small upgrades.<br><em>Big possibilities.</em></h1><p>Discover the little things that make<br>every day a little better.</p><a class="primary" href="#/catalog">Explore the collection <span>→</span></a></div><img class="hero-image" src="'+products[1].image+'" alt="Premium wireless headphones"><div class="hero-dots"><span></span><span></span><span></span></div></section></div><div class="benefits"><div><span class="ico">'+icon('truck')+'</span><span><b>Delivery, made easy</b><small>To your door or a pickup nearby</small></span></div><div><span class="ico">'+icon('shield')+'</span><span><b>Shop with confidence</b><small>Quality finds from trusted brands</small></span></div><div><span class="ico">↶</span><span><b>Changed your mind?</b><small>Easy returns on eligible items</small></span></div><div><span class="ico">♙</span><span><b>Here to help</b><small>Support, whenever you need it</small></span></div></div>'+section('Flash finds',products.slice(0,5),'/catalog?sort=discount','<span class="countdown">Ends in &nbsp; <span id="countdown">05 : 42 : 18</span></span>')+'<section class="section"><div class="section-head"><h2>Find your everyday</h2><a href="#/catalog">Browse all →</a></div><div class="category-tiles">'+categories.slice(0,6).map(c=>'<a class="category-tile" href="#/catalog?category='+encodeURIComponent(c[1])+'"><span class="emoji">'+c[2]+'</span>'+c[1]+'</a>').join('')+'</div></section><div class="promos"><div class="promo"><span class="eyebrow">A SPACE THAT FEELS LIKE YOU</span><h2>Home, a little<br>more lovely.</h2><a href="#/catalog?category=Home%20%26%20Office">Refresh your space →</a><img src="'+products[5].image+'" alt="Nordic accent chair"></div><div class="promo"><span class="eyebrow">MOVE THROUGH YOUR DAY</span><h2>Your pace.<br>Your kind of style.</h2><a href="#/catalog?category=Fashion">Find your fit →</a><img src="'+products[2].image+'" alt="Everyday sneakers"></div></div>'+section('A few favourites for you',products.slice(5,10))}
function catalog(params){const q=params.get('q')||'',cat=params.get('category')||'',brand=params.get('brand')||'',sort=params.get('sort')||'popular',min=Number(params.get('min')||0),max=Number(params.get('max')||100000),official=params.get('official')==='1';let items=products.filter(p=>(!q||(p.name+' '+p.brand+' '+p.category).toLowerCase().includes(q.toLowerCase()))&&(!cat||p.category===cat)&&(!brand||p.brand===brand)&&p.price>=min&&p.price<=max&&(!official||p.official));if(sort==='low')items.sort((a,b)=>a.price-b.price);if(sort==='high')items.sort((a,b)=>b.price-a.price);if(sort==='rating')items.sort((a,b)=>b.rating-a.rating);if(sort==='discount')items.sort((a,b)=>(1-b.price/b.old)-(1-a.price/a.old));const page=Math.max(1,Number(params.get('page'))||1),size=8,pages=Math.ceil(items.length/size);let title=q?'Results for “'+esc(q)+'”':cat|| (official?'Official stores':'Explore all products');return '<div class="crumbs"><a href="#/">Home</a> / '+title+'</div><div class="layout"><aside class="panel filters" id="filters"><form id="filter-form"><input type="hidden" name="q" value="'+esc(q)+'"><h3>CATEGORY</h3><select name="category" aria-label="Category"><option value="">All categories</option>'+categories.map(c=>'<option '+(cat===c[1]?'selected':'')+'>'+c[1]+'</option>').join('')+'</select><h3>BRAND</h3><select name="brand" aria-label="Brand"><option value="">All brands</option>'+[...new Set(products.map(p=>p.brand))].map(b=>'<option '+(brand===b?'selected':'')+'>'+b+'</option>').join('')+'</select><h3>PRICE (GH₵)</h3><div class="two-col"><input aria-label="Minimum price" type="number" min="0" name="min" placeholder="Min" value="'+(min||'')+'"><input aria-label="Maximum price" type="number" min="0" name="max" placeholder="Max" value="'+(max===100000?'':max)+'"></div><label><input type="checkbox" name="official" value="1" '+(official?'checked':'')+'> Official stores only</label><button class="primary full">Apply filters</button><a href="#/catalog" class="small" style="display:block;margin-top:15px">Clear filters</a></form></aside><section><div class="toolbar"><div><h2 style="margin:0;font-size:20px">'+title+'</h2><p class="muted small">'+items.length+' products found</p></div><button class="secondary mobile-filters" data-action="filters">Filters</button><select id="sort" aria-label="Sort products">'+[['popular','Popularity'],['low','Price: low to high'],['high','Price: high to low'],['rating','Top rated'],['discount','Biggest savings']].map(([v,t])=>'<option value="'+v+'" '+(sort===v?'selected':'')+'>'+t+'</option>').join('')+'</select></div>'+(items.length?'<div class="product-grid catalog-grid">'+items.slice((page-1)*size,page*size).map(card).join('')+'</div><nav class="pagination" aria-label="Pages">'+Array.from({length:pages},(_,i)=>{const p=new URLSearchParams(params);p.set('page',i+1);return '<a class="'+(page===i+1?'active':'')+'" href="#/catalog?'+p+'">'+(i+1)+'</a>'}).join('')+'</nav>':'<div class="panel empty"><span class="ico">⌕</span><h2>No matches this time</h2><p class="muted">Try a different search or remove a filter.</p><a href="#/catalog" class="primary">Explore all products</a></div>')+'</section></div>'}
function productPage(id){const p=getP(id);if(!p)return notFound();selectedVariant=p.variants.find(v=>!p.unavailable?.includes(v));const reviews=state.reviews.filter(r=>r.id===id);return '<div class="crumbs"><a href="#/">Home</a> / <a href="#/catalog?category='+encodeURIComponent(p.category)+'">'+p.category+'</a> / '+p.brand+'</div><section class="panel pdp"><div><img class="pdp-image" src="'+p.image+'" alt="'+esc(p.name)+'"><button class="secondary full" data-action="gallery" data-id="'+id+'">View larger image</button></div><div><span class="chip">'+(p.official?'Official store':'Everyday favourite')+'</span><div class="brand" style="margin-top:15px">'+p.brand+'</div><h1>'+p.name+'</h1><a class="rating" href="#reviews"><span class="stars">★★★★★</span> '+p.rating+' · '+(p.reviews+reviews.length)+' ratings</a><div class="price-row"><span class="price">'+money(p.price)+'</span><span class="old">'+money(p.old)+'</span><span class="chip">Save '+Math.round((1-p.price/p.old)*100)+'%</span></div><p class="success">● In stock · '+p.stock+' available</p><div class="small" style="margin-top:24px">CHOOSE A VARIATION '+(id==='sneakers'?'<button class="text" data-action="size-guide" style="float:right;color:var(--orange)">Size guide</button>':'')+'</div><div class="variants">'+p.variants.map(v=>'<button class="variant '+(v===selectedVariant?'active':'')+'" data-action="variant" data-value="'+v+'" '+(p.unavailable?.includes(v)?'disabled':'')+'>'+v+'</button>').join('')+'</div><button class="primary full" data-action="add-selected" data-id="'+id+'">＋ &nbsp; Add to cart</button><button class="secondary full" style="margin-top:10px" data-action="wish" data-id="'+id+'">♡ '+(state.wishlist.includes(id)?'Remove saved item':'Save for later')+'</button><div class="notice">Demo catalog · Product specifications and stock are sample data.</div><h3 class="small">DELIVERY & RETURNS</h3><div class="two-col"><label class="field">Region<select id="pdp-region"><option>Greater Accra</option><option>Ashanti</option><option>Ahafo</option></select></label><label class="field">City<select id="pdp-city"><option>Accra Central</option><option>Tema</option><option>Adenta</option></select></label></div><p class="small" id="estimate">Door delivery '+money(35)+' · Pickup from '+money(14)+'<br><span class="muted">Estimated 2–4 business days. Confirm at checkout.</span></p></div></section><div class="section panel"><nav class="tab-nav"><a href="#details">Product details</a><a href="#specifications">Specifications</a><a href="#reviews">Customer feedback</a></nav><h2 id="details">Made for your everyday</h2><p class="muted">Discover '+esc(p.name)+'. A thoughtful addition to your everyday, from '+p.brand+'.</p><h3 id="specifications">Specifications</h3><div class="cards">'+Object.entries(p.specs).map(([k,v])=>'<div class="summary-row"><span class="muted">'+k+'</span><b>'+v+'</b></div>').join('')+'</div><h3>Sold by '+p.brand+' Store <span class="status">Verified partner</span></h3><button class="secondary" data-action="follow" data-value="'+p.brand+'">'+(state.followed.includes(p.brand)?'Unfollow':'Follow seller')+'</button></div><section class="section panel" id="reviews"><div class="section-head"><h2>Customer feedback</h2><button class="secondary" data-action="review" data-id="'+id+'">Write a review</button></div><span class="stars">★★★★★</span> '+p.rating+' / 5 <span class="muted small">· '+p.reviews+' sample ratings</span>'+reviews.map(r=>'<div class="review"><span class="stars">'+ '★'.repeat(r.rating)+'</span><h4>'+esc(r.title)+'</h4><p>'+esc(r.text)+'</p><span class="small muted">'+esc(r.name)+' · '+r.date+'</span></div>').join('')+'<div class="review"><span class="stars">★★★★★</span><h4>A great everyday find</h4><p class="muted">Just what I was looking for. Easy to use and arrived in good condition.</p><span class="small muted">Sample review · Demo content</span></div></section>'+section('You might also like',products.filter(x=>x.id!==id).slice(0,5))}
function summary(checkout=false){return '<div class="panel"><h3>Order summary</h3><div class="summary-row"><span>Items ('+count()+')</span><b>'+money(subtotal())+'</b></div>'+(checkout?'<div class="summary-row"><span>Delivery</span><b>'+money(ship())+'</b></div>':'')+(state.discount?'<div class="summary-row success"><span>'+esc(state.voucher)+'</span><b>−'+money(discount())+'</b></div>':'')+'<div class="summary-row total"><span>Total</span><span>'+money(checkout?total():subtotal())+'</span></div><p class="small muted">'+(checkout?'Includes selected delivery. Demo prices.':'Delivery calculated at checkout.')+'</p>'+(!checkout?'<a class="primary full" href="#/checkout">Continue to checkout →</a>':'')+'</div>'}
function cartPage(){if(!state.cart.length)return '<h1 class="page-title">Your cart</h1><section class="panel empty"><div class="ico">♧</div><h2>Your next favourite is waiting.</h2><p class="muted">Your cart is empty. Let’s find something you’ll love.</p><a class="primary" href="#/catalog">Start shopping →</a></section>'+section('A little inspiration',products.slice(0,5));return '<div class="crumbs"><a href="#/">Home</a> / Cart</div><h1 class="page-title">Your cart <span class="muted small">('+count()+' items)</span></h1><div class="cart-layout"><div class="panel">'+state.cart.map((l,i)=>{const p=getP(l.id);return '<div class="cart-line"><a href="#/product/'+p.id+'"><img src="'+p.image+'" alt="'+esc(p.name)+'"></a><div><h3>'+p.name+'</h3><div class="small muted">'+esc(l.variant)+' · <span class="success">In stock</span></div><button class="remove" data-action="remove" data-index="'+i+'">♲ Remove</button></div><div><b>'+money(p.price*l.qty)+'</b><div class="quantity" style="margin-top:16px;display:flex"><button data-action="qty" data-index="'+i+'" data-delta="-1" aria-label="Decrease quantity" '+(l.qty===1?'disabled':'')+'>−</button><span>'+l.qty+'</span><button data-action="qty" data-index="'+i+'" data-delta="1" aria-label="Increase quantity" '+(l.qty>=p.stock?'disabled':'')+'>+</button></div></div></div>'}).join('')+'<a class="small" href="#/catalog" style="display:block;margin-top:20px">← Continue shopping</a></div>'+summary()+'</div>'}
const accountLinks=[['','Overview'],['orders','Orders'],['wishlist','Saved items'],['addresses','Address book'],['pickups','Pickup stations'],['vouchers','Vouchers'],['reviews','Pending reviews'],['sellers','Followed sellers'],['inbox','Inbox'],['preferences','Preferences']];
function login(){return '<div style="max-width:460px;margin:40px auto" class="panel"><div class="logo">kstore<span>●</span></div><h1 class="page-title">Welcome to your everyday.</h1><p class="muted">Sign in to save your finds and manage your orders.</p><div class="notice">Demo account · Use any name and a valid email. No password or real account is created.</div><form id="login-form"><label class="field">Your name<input name="name" required maxlength="70" autocomplete="name"></label><label class="field">Email address<input type="email" name="email" required autocomplete="email"></label><button class="primary full">Continue →</button></form></div>'}
function accountPage(tab=''){if(!state.user)return login();return '<div class="crumbs"><a href="#/">Home</a> / My account</div><div class="layout"><aside class="panel account-nav">'+accountLinks.map(([v,t])=>'<a class="'+(tab===v?'active':'')+'" href="#/account'+(v?'/'+v:'')+'">'+t+'</a>').join('')+'<button class="text" style="padding:13px;color:#b33" data-action="logout">Sign out</button></aside><section><h1 class="page-title">'+(accountLinks.find(x=>x[0]===tab)?.[1]||'Overview')+'</h1>'+accountContent(tab)+'</section></div>'}
function accountContent(tab){if(tab==='wishlist')return state.wishlist.length?'<div class="product-grid catalog-grid">'+state.wishlist.map(getP).filter(Boolean).map(card).join('')+'</div>':empty('Keep your favourites close','Tap the heart on a product to save it.');if(tab==='orders')return state.orders.length?state.orders.map(orderCard).join(''):empty('No orders yet','Your demo orders will appear here.');if(tab==='addresses')return '<button class="primary" data-action="address">＋ Add new address</button><div class="spacer"></div><div class="cards">'+state.addresses.map(a=>'<div class="panel"><b>'+esc(a.name)+'</b><p>'+esc(a.address)+'<br>'+esc(a.city)+', '+esc(a.region)+'<br>'+esc(a.phone)+'</p>'+(a.default?'<span class="status">Default</span>':'<button class="text" data-action="default-address" data-value="'+a.id+'">Set default</button>')+'<div class="spacer"></div><button class="secondary" data-action="address" data-value="'+a.id+'">Edit</button> <button class="text" data-action="delete-address" data-value="'+a.id+'">Delete</button></div>').join('')+'</div>';if(tab==='pickups')return '<button class="primary" data-action="pickup">＋ Add pickup station</button>'+state.pickups.map(s=>'<div class="panel" style="margin-top:15px"><h3>'+esc(s.name)+'</h3><p>'+esc(s.city)+', '+esc(s.region)+'</p><p class="small muted">Mon–Fri 8:30–17:30 · Sat 9:00–15:00</p><button data-action="delete-pickup" data-value="'+s.id+'" class="text">Remove</button></div>').join('');if(tab==='vouchers')return '<div class="cards"><div class="panel"><span class="status">Demo voucher</span><h2>10% off your basket</h2><p>Use code <b>WELCOME10</b> at checkout.</p><p class="small muted">Sample promotion · Applies to demo merchandise subtotal.</p><button class="secondary" data-action="copy" data-value="WELCOME10">Copy code</button></div><div class="panel"><h3>Store credit</h3><h2>'+money(0)+'</h2><p class="muted small">No demo credit available.</p></div></div>';if(tab==='reviews'){const ids=[...new Set(state.orders.filter(o=>o.status!=='Cancelled').flatMap(o=>o.lines.map(l=>l.id)))].filter(id=>!state.reviews.some(r=>r.id===id));return ids.length?ids.map(id=>'<div class="panel" style="margin-bottom:12px"><h3>'+getP(id).name+'</h3><button class="secondary" data-action="review" data-id="'+id+'">Write a review</button></div>').join(''):empty('You’re all caught up','Eligible demo purchases will appear here.')}if(tab==='sellers')return state.followed.length?state.followed.map(b=>'<div class="panel" style="margin:12px 0"><h3>'+esc(b)+' Store</h3><a class="secondary" href="#/catalog?brand='+encodeURIComponent(b)+'">Visit store</a> <button class="text" data-action="follow" data-value="'+esc(b)+'">Unfollow</button></div>').join(''):empty('Find your favourite stores','Follow sellers from their product pages.');if(tab==='inbox')return empty('No messages yet','Order updates are shown in your order details.');if(tab==='preferences')return '<form class="panel" id="preferences-form"><h3>Keep in touch</h3><label><input type="checkbox" name="newsletter" '+(state.newsletter?'checked':'')+'> Email me offers and new arrivals</label><div class="spacer"></div><button class="primary">Save preferences</button></form>';return '<h2>Hello, '+esc(state.user.name.split(' ')[0])+'.</h2><p class="muted">A little space for all your favourites.</p><div class="cards"><div class="panel"><h3>Account details</h3><p>'+esc(state.user.name)+'<br>'+esc(state.user.email)+'</p><button class="text" data-action="profile">Edit profile</button></div><div class="panel"><h3>Your shopping</h3><p>'+state.orders.length+' orders · '+state.wishlist.length+' saved items</p><a class="text" href="#/account/orders">View orders →</a></div><div class="panel"><h3>Default address</h3><p>'+esc(state.addresses.find(a=>a.default)?.address||'Add an address for easier checkout.')+'</p><a href="#/account/addresses">Manage addresses →</a></div><div class="panel"><h3>A welcome treat</h3><p>Take 10% off with <b>WELCOME10</b>.</p><a href="#/catalog">Find something good →</a></div></div>'}
function empty(title,text){return '<div class="panel empty"><span class="ico">◇</span><h2>'+title+'</h2><p class="muted">'+text+'</p><a href="#/catalog" class="primary">Explore Kstore →</a></div>'}
function orderCard(o){return '<article class="order panel"><div class="section-head"><h3>'+o.id+'</h3><span class="status">'+o.status+'</span></div><p class="small muted">'+o.date+' · '+o.lines.reduce((s,l)=>s+l.qty,0)+' items · '+money(o.total)+'</p>'+o.lines.map(l=>'<div class="summary-row"><a href="#/product/'+l.id+'">'+getP(l.id).name+' × '+l.qty+'</a><b>'+money(l.price*l.qty)+'</b></div>').join('')+'<div class="order-actions"><button class="secondary" data-action="order-detail" data-value="'+o.id+'">View details</button><button class="secondary" data-action="reorder" data-value="'+o.id+'">Buy again</button>'+(o.status==='Processing'?'<button class="text" data-action="cancel-order" data-value="'+o.id+'">Cancel order</button>':'')+(o.status==='Delivered'?'<button class="text" data-action="return-order" data-value="'+o.id+'">Request return</button>':'')+'</div></article>'}
const stations=[{id:'accra',name:'Kstore Accra Central',region:'Greater Accra',city:'Accra Central'},{id:'tema',name:'Kstore Tema Community 1',region:'Greater Accra',city:'Tema'},{id:'adenta',name:'Kstore Adenta',region:'Greater Accra',city:'Adenta'},{id:'abrepo',name:'Kstore Abrepo',region:'Ashanti',city:'Abrepo'},{id:'adum',name:'Kstore Adum',region:'Ashanti',city:'Adum'},{id:'goaso',name:'Kstore Goaso',region:'Ahafo',city:'Goaso'}];const cities={'Greater Accra':['Accra Central','Tema','Adenta'],Ashanti:['Abrepo','Adum'],Ahafo:['Goaso']};
function addressForm(a={}){modal(a.id?'Edit address':'Add a delivery address','<form id="address-form"><input type="hidden" name="id" value="'+esc(a.id||'')+'"><label class="field">Full name<input name="name" autocomplete="name" required maxlength="70" value="'+esc(a.name||state.user?.name||'')+'"></label><label class="field">Phone number<input name="phone" type="tel" required pattern="[0-9+ ()-]{9,16}" placeholder="024 000 0000" value="'+esc(a.phone||'')+'"></label><label class="field">Street address<input name="address" required minlength="5" maxlength="180" value="'+esc(a.address||'')+'"></label><div class="two-col"><label class="field">Region<select name="region" id="address-region">'+Object.keys(cities).map(r=>'<option '+(a.region===r?'selected':'')+'>'+r+'</option>').join('')+'</select></label><label class="field">City<select name="city" id="address-city">'+cities[a.region||'Greater Accra'].map(c=>'<option '+(a.city===c?'selected':'')+'>'+c+'</option>').join('')+'</select></label></div><label><input name="default" type="checkbox" '+(a.default?'checked':'')+'> Set as default address</label><div class="spacer"></div><button class="primary full">Save address</button></form>')}
function pickupModal(){modal('Find a pickup station','<div class="notice">Sample locations for this demo. No real pickup booking is made.</div><div class="two-col"><label class="field">Region<select id="pickup-region">'+Object.keys(cities).map(r=>'<option>'+r+'</option>').join('')+'</select></label><label class="field">City<select id="pickup-city"><option value="">All cities</option>'+cities['Greater Accra'].map(c=>'<option>'+c+'</option>').join('')+'</select></label></div><div id="pickup-results"></div>');pickupResults()}
function pickupResults(){const region=$('#pickup-region').value,city=$('#pickup-city').value;$('#pickup-results').innerHTML=stations.filter(s=>s.region===region&&(!city||s.city===city)).map(s=>'<div class="order"><h3>'+s.name+'</h3><p class="small muted">'+s.city+' · Mon–Fri 8:30–17:30<br>Pickup fee '+money(14)+'</p><button class="primary" data-action="save-pickup" data-value="'+s.id+'">Select station</button></div>').join('')}
function checkout(){if(!state.cart.length)return empty('Your cart is empty','Add a favourite before checking out.');if(!state.user)return login();const step=state.step||1;return '<div class="crumbs"><a href="#/cart">Cart</a> / Checkout</div><h1 class="page-title">A few steps from yours.</h1><div class="notice">Demo checkout · No money is charged and no real order is placed.</div><nav class="tab-nav">'+[['Delivery',1],['Payment',2],['Review',3]].map(([t,n])=>'<button class="text '+(n===step?'active':'')+'" data-action="checkout-step" data-value="'+n+'" '+(n>step?'disabled':'')+'>'+n+'. '+t+'</button>').join('')+'</nav><div class="cart-layout"><section class="panel">'+(step===1?deliveryStep():step===2?paymentStep():reviewStep())+'</section><aside>'+summary(true)+'<form class="panel" id="voucher-form" style="margin-top:15px"><label class="field">Have a voucher?<div class="inline"><input name="code" placeholder="Enter code" aria-label="Voucher code" value="'+esc(state.voucher)+'"><button class="secondary">Apply</button></div></label><div id="voucher-message" aria-live="polite"></div>'+(state.discount?'<button type="button" data-action="remove-voucher" class="text">Remove voucher</button>':'')+'<p class="small muted">Try WELCOME10 for 10% off.</p></form></aside></div>'}
function deliveryStep(){return '<h2>Where should we send it?</h2><div class="methods"><label><input type="radio" name="delivery" value="door" '+(state.delivery==='door'?'checked':'')+'> Door delivery · '+money(35)+'</label><label><input type="radio" name="delivery" value="pickup" '+(state.delivery==='pickup'?'checked':'')+'> Pickup station · '+money(14)+'</label></div>'+(state.delivery==='door'?state.addresses.map(a=>'<label class="address-choice"><input type="radio" name="address" value="'+a.id+'" '+(state.addressId===a.id?'checked':'')+'> <b>'+esc(a.name)+'</b><p class="small muted">'+esc(a.address)+' · '+esc(a.city)+'</p></label>').join('')+'<button class="secondary" data-action="address">＋ Add address</button>':state.pickups.map(s=>'<label class="address-choice"><input type="radio" name="station" value="'+s.id+'" '+(state.station===s.id?'checked':'')+'> '+esc(s.name)+'<p class="small muted">'+s.city+' · Mon–Fri 8:30–17:30</p></label>').join('')+'<button class="secondary" data-action="pickup">＋ Find pickup station</button>')+'<div class="spacer"></div><button class="primary full" data-action="delivery-next">Continue to payment →</button><p class="small error" id="delivery-error" role="alert"></p>'}
function paymentStep(){return '<h2>Choose how to pay</h2><p class="muted small">Select a demo payment method. No card or wallet details are collected.</p><div class="methods">'+['Card','MTN Mobile Money','Telecel Mobile Money','AirtelTigo Mobile Money','Bank transfer','Pay on delivery'].map(m=>'<label><input type="radio" name="payment" value="'+m+'" '+(state.payment===m?'checked':'')+'> '+m+'</label>').join('')+'</div><div class="notice">In a live store, prepaid methods redirect to a payment provider. This demo simulates the result.</div><button class="primary full" data-action="payment-next">Review order →</button>'}
function reviewStep(){const a=state.delivery==='door'?state.addresses.find(a=>a.id===state.addressId):state.pickups.find(s=>s.id===state.station);return '<h2>Looking good?</h2><h3 class="small">DELIVERY</h3><p>'+esc(a?.name||'')+'</p><p class="small muted">'+esc(a?.address||a?.city||'')+' · '+esc(a?.region||'')+'</p><h3 class="small">PAYMENT</h3><p>'+esc(state.payment)+' <span class="status">Simulated</span></p>'+state.cart.map(l=>'<div class="summary-row"><span>'+getP(l.id).name+'<br><small class="muted">'+esc(l.variant)+' × '+l.qty+'</small></span><b>'+money(getP(l.id).price*l.qty)+'</b></div>').join('')+'<label class="small"><input id="accept-order" type="checkbox"> I understand this creates a demo order only.</label><div class="spacer"></div><button class="primary full" data-action="place-order">Place demo order · '+money(total())+'</button><p id="order-error" class="error" role="alert"></p>'}
function helpPage(){return '<div class="crumbs"><a href="#/">Home</a> / Help center</div><h1 class="page-title">How can we help?</h1><p class="muted">A little guidance for a smoother everyday.</p><div class="help-grid">'+[['shipping','Delivery & pickup'],['returns','Returns & refunds'],['payments','Payment options'],['contact','Contact Kstore'],['terms','Orders & policies'],['about','About us']].map(([id,t])=>'<a href="#/info/'+id+'">'+t+' &nbsp; →</a>').join('')+'</div><section class="panel faq section"><h2>A few common questions</h2>'+[['How do I track my order?','Open My account → Orders → View details. Demo orders include a local status timeline.'],['Can I return an item?','Eligible delivered demo orders have a Request return action. No physical collection or real refund is scheduled.'],['How do vouchers work?','Enter WELCOME10 at checkout for a sample 10% merchandise discount.'],['Where do you deliver?','The demo has sample cities in Greater Accra, Ashanti and Ahafo. A live service needs verified delivery coverage.']].map(([q,a])=>'<details><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'</section>'}
function infoPage(id){const content={about:['Your everyday, upgraded.','Kstore brings together useful finds for home, work and everything in between. This storefront demonstrates a Ghana-focused shopping experience with original Kstore branding.'],shipping:['Delivery, your way.','Choose door delivery or a nearby pickup station at checkout. This demo quotes GH₵35 for door delivery and GH₵14 for pickup. These are sample fees, not a live delivery promise.'],returns:['A little peace of mind.','Demo returns are available from delivered orders. Choose a reason and submit a simulated request. Actual eligibility, collection windows and refund processing must be connected to a live fulfillment service.'],payments:['Ways to pay.','Explore card, bank transfer, MTN, Telecel, AirtelTigo and pay-on-delivery selections. All checkout payments in this version are simulated. Never enter real payment credentials.'],privacy:['Your privacy matters.','This demo stores your entered profile, addresses, cart and orders in browser local storage. It does not create a secure server account. Use sample personal data. You can clear this demo data below.'],terms:['A few things to know.','This is an interactive storefront demonstration. Products, stock, reviews, prices, vouchers and fulfillment are sample data. Checkout creates local demo orders only. No goods are purchased or delivered.'],sell:['Bring your store to Kstore.','Seller onboarding, catalog management and payouts need a live marketplace service. Leave a demo inquiry below to explore the seller form.'],contact:['We’re here to help.','Use the demo contact form below. Messages are confirmed locally and are not sent to a support team.']};const [title,text]=content[id]||content.about;return '<div class="crumbs"><a href="#/">Home</a> / '+title+'</div><section class="panel legal"><h1 class="page-title">'+title+'</h1><p>'+text+'</p>'+(['contact','sell'].includes(id)?'<form id="contact-form"><label class="field">Name<input name="name" required maxlength="70"></label><label class="field">Email<input name="email" type="email" required></label><label class="field">Your message<textarea name="message" required minlength="10" maxlength="2000" rows="5"></textarea></label><button class="primary">Submit demo inquiry</button></form>':'')+(id==='privacy'?'<button class="secondary" data-action="clear-data">Clear browser demo data</button>':'')+'</section>'}
function notFound(){return empty('We couldn’t find that page','Explore the catalog to find your next favourite.')}
function render(){if($('#modal').open)$('#modal').close();const {path,params}=route();let body;if(path==='/')body=home();else if(path==='/catalog')body=catalog(params);else if(path.startsWith('/product/'))body=productPage(path.split('/')[2]);else if(path==='/cart')body=cartPage();else if(path==='/checkout')body=checkout();else if(path.startsWith('/account'))body=accountPage(path.split('/')[2]||'');else if(path==='/help')body=helpPage();else if(path.startsWith('/info/'))body=infoPage(path.split('/')[2]);else body=notFound();$('#app').innerHTML=header()+'<main class="wrap">'+body+'</main>'+footer();document.title=(path==='/'?'Your everyday, upgraded':path==='/catalog'?'Shop all products':path.startsWith('/product/')?getP(path.split('/')[2])?.name||'Product':path.split('/').filter(Boolean).at(-1)||'Home')+' | Kstore';if(params.get('q'))$('#search-input').value=params.get('q');bindSearch()}
function add(id,variant){const p=getP(id);if(!p||p.unavailable?.includes(variant))return toast('Choose an available variation.');const existing=state.cart.find(l=>l.id===id&&l.variant===variant),all=state.cart.filter(l=>l.id===id).reduce((s,l)=>s+l.qty,0);if(all>=p.stock)return toast('The available stock limit has been reached.');if(existing)existing.qty++;else state.cart.push({id,variant,qty:1});state.step=1;save();render();toast('Added to your cart')}
function bindSearch(){const input=$('#search-input'),box=$('#suggestions');input.addEventListener('input',()=>{clearTimeout(input.timer);input.timer=setTimeout(()=>{const q=input.value.trim().toLowerCase();const items=q.length>1?products.filter(p=>(p.name+' '+p.brand).toLowerCase().includes(q)).slice(0,5):[];box.innerHTML=items.map(p=>'<a role="option" href="#/product/'+p.id+'">'+esc(p.name)+'</a>').join('');box.hidden=!items.length;input.setAttribute('aria-expanded',String(!!items.length))},200)});const key=e=>{const els=$$('a',box);if(e.key==='Escape'){box.hidden=true;input.setAttribute('aria-expanded','false');input.focus()}if(e.key==='ArrowDown'&&els.length){e.preventDefault();const i=els.indexOf(document.activeElement);els[(i+1)%els.length].focus()}if(e.key==='ArrowUp'&&els.length){e.preventDefault();const i=els.indexOf(document.activeElement);if(i<=0)input.focus();else els[i-1].focus()}};input.addEventListener('keydown',key);box.addEventListener('keydown',key)}
function requireUser(){if(state.user)return true;go('/account');toast('Sign in to continue');return false}
function orderDetail(o){modal('Order '+o.id,'<span class="status">'+o.status+'</span><p>'+o.date+' · '+money(o.total)+'</p><h3>Delivery</h3><p>'+esc(o.destination)+'</p><p class="small">Payment: '+esc(o.payment)+' · '+esc(o.paymentStatus)+'</p><h3>Timeline</h3><p class="small">✓ Demo order received<br>✓ Inventory validated<br>'+ (o.status==='Delivered'?'✓ Delivered':o.status==='Cancelled'?'× Cancelled':'○ Processing')+'</p><div class="notice">Demo controls below simulate fulfillment. They do not change a real shipment.</div>'+(o.status==='Processing'?'<button class="secondary" data-action="deliver-demo" data-value="'+o.id+'">Simulate delivered</button>':'')+o.lines.map(l=>'<p class="small">'+getP(l.id).name+' × '+l.qty+'</p>').join(''))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,v=b.dataset.value,i=Number(b.dataset.index);if(a==='close')return $('#modal').close();if(a==='menu')return modal('Explore categories',categories.map(c=>'<a style="display:block;padding:13px" href="#/catalog?category='+encodeURIComponent(c[1])+'">'+c[2]+' &nbsp; '+c[1]+'</a>').join(''));if(a==='filters')return $('#filters').classList.toggle('open');if(a==='wish'){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];save();render();return toast('Saved items updated')}if(a==='variant'){selectedVariant=v;$$('.variant').forEach(x=>x.classList.toggle('active',x.dataset.value===v));return}if(a==='add-selected')return add(id,selectedVariant);if(a==='add-picker'){const p=getP(id);if(p.variants.filter(v=>!p.unavailable?.includes(v)).length===1)return add(id,p.variants.find(v=>!p.unavailable?.includes(v)));return modal('Choose your variation',p.variants.map(v=>'<button class="variant" style="margin:5px" data-action="add-variant" data-id="'+id+'" data-value="'+v+'" '+(p.unavailable?.includes(v)?'disabled':'')+'>'+v+'</button>').join(''))}if(a==='add-variant'){$('#modal').close();return add(id,v)}if(a==='gallery')return modal(getP(id).name,'<img style="width:100%;height:340px;object-fit:contain" src="'+getP(id).image+'" alt="'+esc(getP(id).name)+'">');if(a==='size-guide')return modal('Find your fit','<p class="muted small">Measure from heel to longest toe. If between sizes, choose the larger size.</p><table><thead><tr><th>EU</th><th>UK</th><th>Foot length</th></tr></thead><tbody>'+[40,41,42,43,44].map((n,i)=>'<tr><td>'+n+'</td><td>'+(6+i)+'</td><td>'+(24.8+i*.65).toFixed(1)+' cm</td></tr>').join('')+'</tbody></table>');if(a==='qty'){const l=state.cart[i],p=getP(l.id),n=l.qty+Number(b.dataset.delta),all=state.cart.filter(x=>x.id===l.id).reduce((s,x)=>s+x.qty,0);if(n<1||all+Number(b.dataset.delta)>p.stock)return toast('Quantity is outside available stock.');l.qty=n;state.step=1;save();render();return}if(a==='remove')return modal('Remove this item?','<p class="muted">You can save it for another day.</p><div class="order-actions"><button class="secondary" data-action="save-line" data-index="'+i+'">Save for later</button><button class="primary" data-action="remove-line" data-index="'+i+'">Remove item</button></div>');if(a==='remove-line'||a==='save-line'){if(a==='save-line'&&!state.wishlist.includes(state.cart[i].id))state.wishlist.push(state.cart[i].id);state.cart.splice(i,1);state.step=1;save();render();return}if(a==='follow'){if(!requireUser())return;state.followed=state.followed.includes(v)?state.followed.filter(x=>x!==v):[...state.followed,v];save();render();return toast('Seller preferences updated')}if(a==='address'){if(!requireUser())return;return addressForm(state.addresses.find(x=>x.id===v))}if(a==='default-address'){state.addresses.forEach(x=>x.default=x.id===v);state.addressId=v;save();render();return}if(a==='delete-address')return modal('Delete address?','<p>This removes the saved demo address from this browser.</p><button class="primary" data-action="confirm-delete-address" data-value="'+v+'">Delete address</button>');if(a==='confirm-delete-address'){state.addresses=state.addresses.filter(x=>x.id!==v);if(state.addressId===v)state.addressId='';state.step=1;save();render();return}if(a==='pickup'){if(requireUser())pickupModal();return}if(a==='save-pickup'){const s=stations.find(s=>s.id===v);if(!state.pickups.some(x=>x.id===v))state.pickups.push(s);state.station=v;save();render();return toast('Pickup station saved')}if(a==='delete-pickup'){state.pickups=state.pickups.filter(s=>s.id!==v);if(state.station===v)state.station='';state.step=1;save();render();return}if(a==='checkout-step'){state.step=Number(v);save();render();return}if(a==='delivery-next'){if(state.delivery==='door'&&!state.addresses.some(a=>a.id===state.addressId))return $('#delivery-error').textContent='Select or add a delivery address.';if(state.delivery==='pickup'&&!state.pickups.some(s=>s.id===state.station))return $('#delivery-error').textContent='Select or add a pickup station.';state.step=2;save();render();return}if(a==='payment-next'){state.step=3;save();render();return}if(a==='remove-voucher'){state.discount=0;state.voucher='';save();render();return}if(a==='place-order'){if(!$('#accept-order').checked)return $('#order-error').textContent='Please acknowledge the demo order.';const dest=state.delivery==='door'?state.addresses.find(a=>a.id===state.addressId):state.pickups.find(a=>a.id===state.station);if(!dest||!state.cart.length)return toast('Recheck your cart and delivery choice.');if(state.cart.some(l=>l.qty<1||l.qty>getP(l.id).stock))return toast('An item exceeds available stock.');const o={id:'KS-'+Date.now().toString().slice(-8),date:new Date().toLocaleDateString('en-GB'),status:'Processing',payment:state.payment,paymentStatus:state.payment==='Pay on delivery'?'Due on delivery (demo)':'Simulated payment accepted',destination:[dest.name,dest.address,dest.city,dest.region].filter(Boolean).join(', '),lines:state.cart.map(l=>({...l,price:getP(l.id).price})),subtotal:subtotal(),shipping:ship(),discount:discount(),total:total()};state.orders.unshift(o);state.cart=[];state.discount=0;state.voucher='';state.step=1;save();go('/account/orders');toast('Demo order '+o.id+' created. No payment was charged.');return}if(a==='logout'){state.user=null;save();go('/');toast('Signed out');return}if(a==='profile')return modal('Edit profile','<form id="profile-form"><label class="field">Name<input name="name" required value="'+esc(state.user.name)+'"></label><label class="field">Email<input name="email" type="email" required value="'+esc(state.user.email)+'"></label><button class="primary">Save profile</button></form>');if(a==='copy'){navigator.clipboard?.writeText(v).then(()=>toast('Code copied')).catch(()=>toast('Use code '+v));return}if(a==='review'){if(!requireUser())return;if(!state.orders.some(o=>o.status!=='Cancelled'&&o.lines.some(l=>l.id===id)))return toast('Create a demo purchase of this item before reviewing.');return modal('Share your thoughts','<form id="review-form"><input type="hidden" name="id" value="'+id+'"><label class="field">Rating<select name="rating"><option value="5">5 — Love it</option><option value="4">4 — Good</option><option value="3">3 — Okay</option><option value="2">2 — Could be better</option><option value="1">1 — Disappointed</option></select></label><label class="field">Title<input name="title" required maxlength="100"></label><label class="field">Your review<textarea name="text" required minlength="10" maxlength="1000" rows="4"></textarea></label><button class="primary">Publish demo review</button></form>')}const o=state.orders.find(o=>o.id===v);if(a==='order-detail')return orderDetail(o);if(a==='deliver-demo'){o.status='Delivered';save();render();return toast('Demo delivery completed')}if(a==='reorder'){o.lines.forEach(l=>{const p=getP(l.id),existing=state.cart.find(x=>x.id===l.id&&x.variant===l.variant);if(existing)existing.qty=Math.min(existing.qty+l.qty,p.stock);else state.cart.push({id:l.id,variant:l.variant,qty:Math.min(l.qty,p.stock)})});state.step=1;save();go('/cart');return}if(a==='cancel-order')return modal('Cancel demo order?','<p>Your simulated order will be marked cancelled.</p><button class="primary" data-action="confirm-cancel" data-value="'+v+'">Confirm cancellation</button>');if(a==='confirm-cancel'){o.status='Cancelled';o.paymentStatus='Simulated refund completed';save();render();return toast('Demo order cancelled')}if(a==='return-order')return modal('Request a demo return','<form id="return-form"><input type="hidden" name="id" value="'+v+'"><label class="field">Reason<select name="reason"><option>Changed my mind</option><option>Damaged item</option><option>Wrong item</option><option>Not as described</option></select></label><button class="primary">Submit demo return</button></form>');if(a==='clear-data')return modal('Clear all demo data?','<p>This removes your browser-local profile, cart, addresses and demo orders.</p><button class="primary" data-action="confirm-clear">Clear demo data</button>');if(a==='confirm-clear'){localStorage.removeItem('kstore-v1');state=JSON.parse(JSON.stringify(defaults));render();toast('Demo data cleared')}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='sort'){const p=route().params;p.set('sort',el.value);p.delete('page');go('/catalog?'+p)}if(el.name==='delivery'){state.delivery=el.value;state.step=1;save();render()}if(el.name==='address'){state.addressId=el.value;save()}if(el.name==='station'){state.station=el.value;save()}if(el.name==='payment'){state.payment=el.value;save()}if(el.id==='address-region')$('#address-city').innerHTML=cities[el.value].map(c=>'<option>'+c+'</option>').join('');if(el.id==='pickup-region'){$('#pickup-city').innerHTML='<option value="">All cities</option>'+cities[el.value].map(c=>'<option>'+c+'</option>').join('');pickupResults()}if(el.id==='pickup-city')pickupResults();if(el.id==='pdp-region'){$('#pdp-city').innerHTML=cities[el.value].map(c=>'<option>'+c+'</option>').join('');$('#estimate').innerHTML='Door delivery '+money(el.value==='Greater Accra'?35:45)+' · Pickup '+money(14)+'<br><span class="muted">Sample estimate · Final demo fee shown at checkout.</span>'}});
document.addEventListener('submit',e=>{const f=e.target;const formId=f.getAttribute('id');if(!formId)return;e.preventDefault();const d=Object.fromEntries(new FormData(f));if(formId==='search-form')go('/catalog?q='+encodeURIComponent(d.q.trim()));if(formId==='filter-form'){if(d.min&&d.max&&Number(d.min)>Number(d.max))return toast('Minimum price must not exceed maximum.');go('/catalog?'+new URLSearchParams(Object.entries(d).filter(([k,v])=>v!=='')))}if(formId==='login-form'){state.user={name:d.name.trim(),email:d.email.trim()};save();if(route().path==='/checkout')render();else go('/account');toast('Welcome to Kstore, '+state.user.name.split(' ')[0])}if(formId==='profile-form'){state.user={name:d.name.trim(),email:d.email.trim()};save();render();toast('Profile updated')}if(formId==='address-form'){if(!cities[d.region]?.includes(d.city))return toast('Choose a city within the selected region.');const a={id:d.id||'addr-'+Date.now(),name:d.name.trim(),phone:d.phone.trim(),address:d.address.trim(),region:d.region,city:d.city,default:!!d.default||state.addresses.length===0};if(a.default)state.addresses.forEach(x=>x.default=false);const i=state.addresses.findIndex(x=>x.id===a.id);if(i>=0)state.addresses[i]=a;else state.addresses.push(a);state.addressId=a.id;save();render();toast('Address saved')}if(formId==='voucher-form'){const code=d.code.trim().toUpperCase();if(code!=='WELCOME10'){$('#voucher-message').className='error';$('#voucher-message').textContent=code?'Voucher not found':'Enter a voucher code.';return}state.voucher=code;state.discount=.1;save();render();toast('10% demo discount applied')}if(formId==='newsletter-form'){state.newsletter=true;save();f.reset();toast('Demo newsletter preference saved. No email was sent.')}if(formId==='preferences-form'){state.newsletter=!!d.newsletter;save();toast('Preferences saved')}if(formId==='review-form'){if(state.reviews.some(r=>r.id===d.id))return toast('You have already reviewed this item.');state.reviews.push({...d,rating:Number(d.rating),name:state.user.name,date:new Date().toLocaleDateString('en-GB')});save();render();toast('Demo review published')}if(formId==='return-form'){const o=state.orders.find(o=>o.id===d.id);o.status='Return requested';o.returnReason=d.reason;o.paymentStatus='Simulated refund pending';save();render();toast('Demo return requested. No collection was booked.')}if(formId==='contact-form'){f.reset();toast('Demo inquiry recorded locally. No message was sent.')}});
window.addEventListener('hashchange',()=>{if(['#details','#specifications','#reviews'].includes(location.hash))return;render();window.scrollTo(0,0)});document.addEventListener('click',e=>{const a=e.target.closest('a[href="#details"],a[href="#specifications"],a[href="#reviews"]');if(a){e.preventDefault();$(a.getAttribute('href'))?.scrollIntoView({behavior:'smooth',block:'start'})}});setInterval(()=>{const el=$('#countdown');if(!el)return;const remaining=86400-Math.floor(Date.now()/1000)%86400;el.textContent=[Math.floor(remaining/3600),Math.floor(remaining%3600/60),remaining%60].map(n=>String(n).padStart(2,'0')).join(' : ')},1000);render();
